#!/usr/bin/env python3
"""Offline DNS model-based regression workbench.

Reads one JSON document from stdin, validates it against the frozen input
contract, simulates the local resolution model for every query/profile pair,
adjudicates the supplied observations and selects an exact minimum-cost
diagnostic basis.  Exactly one JSON document is written to stdout.
"""

import ipaddress
import json
import re
import sys


class Invalid(Exception):
    """Any condition that makes the input document invalid."""


# ---------------------------------------------------------------------------
# input bounds
# ---------------------------------------------------------------------------

MAX_BYTES = 8 * 1024 * 1024
MAX_DEPTH = 32

TYPES = ('A', 'AAAA', 'TXT', 'CNAME')
RCODES = ('NOERROR', 'NXDOMAIN', 'SERVFAIL', 'REFUSED')
CNAME_MODES = ('follow', 'stop')
WILDCARD_MODES = ('rfc', 'off', 'one-label')

ID_RE = re.compile(r'[A-Za-z0-9_-]{1,32}')
LABEL_RE = re.compile(r'[A-Za-z0-9_-]{1,63}')
OCTET_RE = re.compile(r'[0-9]{1,3}')


# ---------------------------------------------------------------------------
# lexical helpers
# ---------------------------------------------------------------------------

def v_id(value):
    if type(value) is not str or ID_RE.fullmatch(value) is None:
        raise Invalid()
    return value


def v_name(value):
    """Validate an absolute domain name, return its canonical (lowercase) form."""
    if type(value) is not str:
        raise Invalid()
    if value == '.':
        return '.'
    if len(value) < 2 or value[-1] != '.':
        raise Invalid()
    labels = value[:-1].split('.')
    total = 1
    for label in labels:
        if label == '*':
            size = 1
        else:
            if LABEL_RE.fullmatch(label) is None:
                raise Invalid()
            size = len(label)
        total += size + 1
    if total > 255:
        raise Invalid()
    return value.lower()


def v_ipv4(value):
    parts = value.split('.')
    if len(parts) != 4:
        raise Invalid()
    out = []
    for part in parts:
        if OCTET_RE.fullmatch(part) is None:
            raise Invalid()
        if len(part) > 1 and part[0] == '0':
            raise Invalid()
        octet = int(part)
        if octet > 255:
            raise Invalid()
        out.append(str(octet))
    return '.'.join(out)


def v_data(value, rtype):
    if type(value) is not str:
        raise Invalid()
    if rtype == 'A':
        return v_ipv4(value)
    if rtype == 'AAAA':
        if '%' in value:
            raise Invalid()
        try:
            return ipaddress.IPv6Address(value).compressed
        except Exception:
            raise Invalid()
    if rtype == 'TXT':
        if len(value) > 256:
            raise Invalid()
        for ch in value:
            if not 0x20 <= ord(ch) <= 0x7E:
                raise Invalid()
        return value
    return v_name(value)


def v_record(obj):
    if type(obj) is not dict or set(obj.keys()) != {'owner', 'type', 'data'}:
        raise Invalid()
    owner = v_name(obj['owner'])
    rtype = obj['type']
    if type(rtype) is not str or rtype not in TYPES:
        raise Invalid()
    return owner, rtype, v_data(obj['data'], rtype)


def v_int(value, low, high):
    if type(value) is not int:
        raise Invalid()
    if value < low or value > high:
        raise Invalid()
    return value


# ---------------------------------------------------------------------------
# JSON decoding (duplicate keys, nonfinite numbers, nesting depth)
# ---------------------------------------------------------------------------

def _pairs_hook(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise Invalid()
        obj[key] = value
    return obj


def _constant(_name):
    raise Invalid()


def _walk_depth(node, depth):
    if depth > MAX_DEPTH:
        raise Invalid()
    kind = type(node)
    if kind is dict:
        for value in node.values():
            _walk_depth(value, depth + 1)
    elif kind is list:
        for value in node:
            _walk_depth(value, depth + 1)
    elif kind is float:
        raise Invalid()


def load_document(raw):
    if len(raw) > MAX_BYTES:
        raise Invalid()
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid()
    try:
        document = json.loads(text, object_pairs_hook=_pairs_hook,
                              parse_constant=_constant)
    except Invalid:
        raise
    except Exception:
        raise Invalid()
    _walk_depth(document, 1)
    return document


# ---------------------------------------------------------------------------
# name utilities
# ---------------------------------------------------------------------------

_label_cache = {}


def labels_of(name):
    cached = _label_cache.get(name)
    if cached is None:
        cached = [] if name == '.' else name[:-1].split('.')
        _label_cache[name] = cached
    return cached


def suffix_name(labels, skip):
    """Name obtained by dropping the leading `skip` labels."""
    rest = labels[skip:]
    if not rest:
        return '.'
    return '.'.join(rest) + '.'


def at_or_below(owner_labels, origin_labels):
    extra = len(owner_labels) - len(origin_labels)
    if extra < 0:
        return False
    if not origin_labels:
        return True
    return owner_labels[extra:] == origin_labels


# ---------------------------------------------------------------------------
# zones
# ---------------------------------------------------------------------------

def build_zones(raw_zones):
    by_origin = {}
    total_entries = 0
    for raw in raw_zones:
        if type(raw) is not dict or set(raw.keys()) != {'origin', 'records'}:
            raise Invalid()
        origin = v_name(raw['origin'])
        if origin in by_origin:
            raise Invalid()
        raw_records = raw['records']
        if type(raw_records) is not list:
            raise Invalid()
        origin_labels = labels_of(origin)
        rrsets = {}
        for raw_record in raw_records:
            owner, rtype, data = v_record(raw_record)
            owner_labels = labels_of(owner)
            if not at_or_below(owner_labels, origin_labels):
                raise Invalid()
            total_entries += 1
            if total_entries > 1024:
                raise Invalid()
            types = rrsets.get(owner)
            if types is None:
                types = rrsets[owner] = {}
            if rtype == 'CNAME':
                if owner == origin:
                    raise Invalid()
                if 'CNAME' in types:
                    if data not in types['CNAME']:
                        raise Invalid()
                else:
                    if types:
                        raise Invalid()
                    types['CNAME'] = {data}
            else:
                if 'CNAME' in types:
                    raise Invalid()
                dataset = types.get(rtype)
                if dataset is None:
                    dataset = types[rtype] = set()
                dataset.add(data)
                if len(dataset) > 64:
                    raise Invalid()
        existing = {origin}
        for owner in rrsets:
            owner_labels = labels_of(owner)
            for skip in range(len(owner_labels) - len(origin_labels) + 1):
                existing.add(suffix_name(owner_labels, skip))
        by_origin[origin] = {
            'rr': {owner: {rtype: tuple(sorted(datas))
                           for rtype, datas in types.items()}
                   for owner, types in rrsets.items()},
            'existing': existing,
        }
    return by_origin


# ---------------------------------------------------------------------------
# profiles / queries / observations
# ---------------------------------------------------------------------------

def build_profiles(raw_profiles):
    if type(raw_profiles) is not list or not 1 <= len(raw_profiles) <= 8:
        raise Invalid()
    profiles = {}
    for raw in raw_profiles:
        if type(raw) is not dict or set(raw.keys()) != {
                'id', 'max_aliases', 'cname', 'wildcard'}:
            raise Invalid()
        pid = v_id(raw['id'])
        if pid in profiles:
            raise Invalid()
        cname = raw['cname']
        if type(cname) is not str or cname not in CNAME_MODES:
            raise Invalid()
        wildcard = raw['wildcard']
        if type(wildcard) is not str or wildcard not in WILDCARD_MODES:
            raise Invalid()
        profiles[pid] = {
            'id': pid,
            'max_aliases': v_int(raw['max_aliases'], 0, 64),
            'cname': cname,
            'wildcard': wildcard,
        }
    return profiles


def build_queries(raw_queries):
    if type(raw_queries) is not list or len(raw_queries) > 20:
        raise Invalid()
    queries = {}
    for raw in raw_queries:
        if type(raw) is not dict or set(raw.keys()) != {
                'id', 'name', 'type', 'cost'}:
            raise Invalid()
        qid = v_id(raw['id'])
        if qid in queries:
            raise Invalid()
        rtype = raw['type']
        if type(rtype) is not str or rtype not in TYPES:
            raise Invalid()
        queries[qid] = {
            'id': qid,
            'name': v_name(raw['name']),
            'type': rtype,
            'cost': v_int(raw['cost'], 1, 1000),
        }
    return queries


def build_observations(raw_observations, queries, profiles):
    if type(raw_observations) is not list or len(raw_observations) > 64:
        raise Invalid()
    observations = {}
    for raw in raw_observations:
        if type(raw) is not dict or set(raw.keys()) != {
                'id', 'query', 'profile', 'result'}:
            raise Invalid()
        oid = v_id(raw['id'])
        if oid in observations:
            raise Invalid()
        qid = v_id(raw['query'])
        pid = v_id(raw['profile'])
        if qid not in queries or pid not in profiles:
            raise Invalid()
        result = raw['result']
        if type(result) is not dict:
            raise Invalid()
        keys = set(result.keys())
        if keys == {'status'}:
            if result['status'] != 'timeout':
                raise Invalid()
            observed = ('timeout', None, None)
        elif keys == {'status', 'rcode', 'answer'}:
            if result['status'] != 'response':
                raise Invalid()
            rcode = result['rcode']
            if type(rcode) is not str or rcode not in RCODES:
                raise Invalid()
            answer = result['answer']
            if type(answer) is not list or len(answer) > 128:
                raise Invalid()
            observed = ('response', rcode,
                        frozenset(v_record(rec) for rec in answer))
        else:
            raise Invalid()
        observations[oid] = {'id': oid, 'query': qid, 'profile': pid,
                             'result': observed}
    return observations


# ---------------------------------------------------------------------------
# resolution model
# ---------------------------------------------------------------------------

def resolve(qname, qtype, profile, by_origin):
    cname_mode = profile['cname']
    wildcard_mode = profile['wildcard']
    max_aliases = profile['max_aliases']

    current = qname
    seen = set()
    followed = 0
    answer = []
    trace = []

    while True:
        trace.append(current)
        if current in seen:
            return 'SERVFAIL', 'LOOP', current, answer, trace
        seen.add(current)

        current_labels = labels_of(current)
        zone = None
        for skip in range(len(current_labels) + 1):
            zone = by_origin.get(suffix_name(current_labels, skip))
            if zone is not None:
                break
        if zone is None:
            if followed == 0:
                return 'REFUSED', 'OUTSIDE', current, answer, trace
            return 'NOERROR', 'EXTERNAL', current, answer, trace

        existing = zone['existing']
        rrsets = zone['rr']

        source = None
        if current in existing:
            source = current
        elif wildcard_mode != 'off':
            encloser = None
            for skip in range(1, len(current_labels) + 1):
                candidate = suffix_name(current_labels, skip)
                if candidate in existing:
                    encloser = candidate
                    break
            if encloser is not None:
                source = '*.' if encloser == '.' else '*.' + encloser
                if source not in existing:
                    source = None
                elif wildcard_mode == 'one-label' and \
                        len(current_labels) != len(labels_of(encloser)) + 1:
                    source = None
        if source is None:
            return 'NXDOMAIN', 'NXDOMAIN', current, answer, trace

        at_source = rrsets.get(source)
        cname = at_source.get('CNAME') if at_source else None

        if qtype == 'CNAME':
            if cname:
                answer.append((current, 'CNAME', cname[0]))
                return 'NOERROR', 'ANSWER', current, answer, trace
            return 'NOERROR', 'NODATA', current, answer, trace

        if cname:
            if cname_mode == 'stop':
                answer.append((current, 'CNAME', cname[0]))
                return 'NOERROR', 'CNAME_STOP', current, answer, trace
            if followed == max_aliases:
                return 'SERVFAIL', 'LIMIT', current, answer, trace
            answer.append((current, 'CNAME', cname[0]))
            followed += 1
            current = cname[0]
            continue

        wanted = at_source.get(qtype) if at_source else None
        if wanted:
            for data in wanted:
                answer.append((current, qtype, data))
            return 'NOERROR', 'ANSWER', current, answer, trace
        return 'NOERROR', 'NODATA', current, answer, trace


# ---------------------------------------------------------------------------
# diagnostic basis (exact minimum-cost set cover over profile partitions)
# ---------------------------------------------------------------------------

def refine(state, partition):
    mapping = {}
    out = []
    for left, right in zip(state, partition):
        key = (left, right)
        index = mapping.get(key)
        if index is None:
            index = mapping[key] = len(mapping)
        out.append(index)
    return tuple(out)


def select_basis(profile_ids, query_ids, signature, costs):
    count_profiles = len(profile_ids)
    index_of = {pid: i for i, pid in enumerate(profile_ids)}

    # equivalence classes over the full candidate set
    class_of = {}
    classes = []
    for pid in profile_ids:
        key = tuple(signature[(qid, pid)] for qid in query_ids)
        target = class_of.get(key)
        if target is None:
            target = class_of[key] = len(classes)
            classes.append([])
        classes[target].append(pid)
    equivalence = sorted(classes)
    target_state = tuple(class_of[
        tuple(signature[(qid, pid)] for qid in query_ids)]
        for pid in profile_ids)

    # per-query partitions
    partitions = []
    for qid in query_ids:
        mapping = {}
        arr = []
        for pid in profile_ids:
            sig = signature[(qid, pid)]
            block = mapping.get(sig)
            if block is None:
                block = mapping[sig] = len(mapping)
            arr.append(block)
        partitions.append(tuple(arr))

    start = tuple([0] * count_profiles)
    dp = {start: (0, 0, ())}
    for qi, partition in enumerate(partitions):
        cost = costs[query_ids[qi]]
        nxt = dict(dp)
        for state, value in dp.items():
            new_state = refine(state, partition)
            if new_state == state:
                continue
            candidate = (value[0] + cost, value[1] + 1)
            previous = nxt.get(new_state)
            if previous is None or candidate < (previous[0], previous[1]):
                nxt[new_state] = (candidate[0], candidate[1],
                                  value[2] + (qi,))
        dp = nxt
    best = dp[target_state]
    basis = sorted(query_ids[qi] for qi in best[2])
    return equivalence, basis, best[0], best[1]


# ---------------------------------------------------------------------------
# top level
# ---------------------------------------------------------------------------

def analyze(document):
    if type(document) is not dict or set(document.keys()) != {
            'zones', 'profiles', 'queries', 'observations'}:
        raise Invalid()
    by_origin = build_zones(document['zones'])
    profiles = build_profiles(document['profiles'])
    queries = build_queries(document['queries'])
    observations = build_observations(
        document['observations'], queries, profiles)

    profile_ids = sorted(profiles)
    query_ids = sorted(queries)

    runs = []
    signature = {}
    for qid in query_ids:
        query = queries[qid]
        for pid in profile_ids:
            rcode, termination, final_name, answer, trace = resolve(
                query['name'], query['type'], profiles[pid], by_origin)
            runs.append({
                'query': qid,
                'profile': pid,
                'rcode': rcode,
                'termination': termination,
                'final_name': final_name,
                'answer': [{'owner': owner, 'type': rtype, 'data': data}
                           for owner, rtype, data in answer],
                'trace': list(trace),
            })
            signature[(qid, pid)] = (rcode, frozenset(answer))

    audits = []
    for oid in sorted(observations):
        observation = observations[oid]
        status, rcode, records = observation['result']
        if status == 'timeout':
            audits.append({'id': oid, 'verdict': 'unobserved',
                           'different': []})
            continue
        run = signature[(observation['query'], observation['profile'])]
        different = []
        if run[0] != rcode:
            different.append('rcode')
        if run[1] != records:
            different.append('answer')
        audits.append({'id': oid,
                       'verdict': 'match' if not different else 'divergence',
                       'different': different})

    equivalence, basis, cost, count = select_basis(
        profile_ids, query_ids, signature,
        {qid: queries[qid]['cost'] for qid in query_ids})

    return {
        'runs': runs,
        'audits': audits,
        'diagnostic': {
            'equivalence': equivalence,
            'basis': basis,
            'cost': cost,
            'count': count,
        },
    }


def main():
    raw = sys.stdin.buffer.read()
    try:
        document = load_document(raw)
        result = analyze(document)
        text = json.dumps(result, separators=(',', ':'))
    except Exception:
        text = '{"error":"invalid-input"}'
    sys.stdout.write(text + '\n')


if __name__ == '__main__':
    main()
